import { createServer } from 'node:https';
import assert from 'node:assert/strict';
import { once } from 'node:events';
import { createDenoPinnedRequest } from '../functions/link-preview/denoTransport.ts';

// A temporary self-signed fixture is generated by the documented OpenSSL test
// command. No production certificates, credentials, DNS or external server is
// involved. The test intentionally calls the low-level transport at loopback;
// createSafeFetch's independent public-IP policy is covered by the Node suite.
const fixture=Deno.env.get('PLATINUM_LINK_TLS_FIXTURE');
if(!fixture)throw new Error('PLATINUM_LINK_TLS_FIXTURE must point to the temporary TLS fixture');
const key=await Deno.readTextFile(`${fixture}/key.pem`),cert=await Deno.readTextFile(`${fixture}/cert.pem`);

Deno.test('Deno real HTTPS pins the IP, sends the original Host/SNI and validates that certificate name',async()=>{
 const requests: {host?:string;authorization?:string;cookie?:string;url?:string}[]=[];
 const server=createServer({key,cert},(req,res)=>{requests.push({host:req.headers.host,authorization:req.headers.authorization,cookie:req.headers.cookie,url:req.url});res.writeHead(200,{'Content-Type':'text/html'});res.end('<title>Local verified TLS</title>');});
 server.listen(0,'127.0.0.1');await once(server,'listening');
 const address=server.address();assert.ok(address && typeof address!=='string');
 const connected: string[]=[],names:string[]=[];
 const pinned=createDenoPinnedRequest({connect:options=>{connected.push(options.hostname);return Deno.connect({...options,port:address.port});},
  startTls:(connection,options)=>{names.push(options.hostname);assert.deepEqual(options.alpnProtocols,['http/1.1']);return Deno.startTls(connection as Deno.TcpConn,{...options,caCerts:[cert]});}});
 try {
  const response=await pinned(new URL('https://preview.example.com/path?item=1'),{address:'127.0.0.1',family:4},'html',new AbortController().signal);
  assert.equal(new TextDecoder().decode(response.bytes),'<title>Local verified TLS</title>');
  assert.deepEqual(connected,['127.0.0.1']);assert.deepEqual(names,['preview.example.com']);assert.deepEqual(requests,[{host:'preview.example.com',authorization:undefined,cookie:undefined,url:'/path?item=1'}]);
  await assert.rejects(pinned(new URL('https://wrong.example.com/'),{address:'127.0.0.1',family:4},'html',new AbortController().signal),/upstream/);
  assert.equal(requests.length,1,'A hostname mismatch must fail before sending an HTTP request');
  const untrusted=createDenoPinnedRequest({connect:options=>Deno.connect({...options,port:address.port}),startTls:(connection,options)=>Deno.startTls(connection as Deno.TcpConn,options)});
  await assert.rejects(untrusted(new URL('https://preview.example.com/'),{address:'127.0.0.1',family:4},'html',new AbortController().signal),/upstream/);
  assert.equal(requests.length,1,'An untrusted CA must fail before sending an HTTP request');
 }finally{server.closeAllConnections();await new Promise<void>(resolve=>server.close(()=>resolve()));}
});

Deno.test('Deno real HTTPS cancellation closes an unfinished response',async()=>{
 const server=createServer({key,cert},(_req,res)=>{res.writeHead(200,{'Content-Type':'text/html'});res.write('<title>unfinished');});
 server.listen(0,'127.0.0.1');await once(server,'listening');const address=server.address();assert.ok(address && typeof address!=='string');
 const pinned=createDenoPinnedRequest({connect:options=>Deno.connect({...options,port:address.port}),startTls:(connection,options)=>Deno.startTls(connection as Deno.TcpConn,{...options,caCerts:[cert]})});
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),100);
 try {await assert.rejects(pinned(new URL('https://preview.example.com/'),{address:'127.0.0.1',family:4},'html',controller.signal),/timeout/);}
 finally{clearTimeout(timer);server.closeAllConnections();await new Promise<void>(resolve=>server.close(()=>resolve()));}
});
